-- ============================================================================
-- GARMIN TRAINING HUB — MIGRAÇÃO 134: Reformula por completo o módulo
-- "Garmin Connect" (Zona Atleta) — de página de consulta de funcionalidades
-- para treinamento de produto de integração
-- ============================================================================
-- Brief completo enviado pelo usuário no chat (2026-09-15): o novo
-- colaborador precisa terminar o módulo sabendo reconhecer uma métrica na
-- tela do Garmin Connect, entender o que ela significa, explicar para o
-- cliente e relacioná-la com uma necessidade real — não apenas memorizar
-- nomes. Lógica pedagógica: entender → reconhecer → interpretar → explicar
-- → aplicar.
--
-- De 4 para 15 lições (reaproveita as 4 existentes, insere 11 novas — mesmo
-- padrão de sql/125/129/133 nesta sessão). Nenhum componente novo: reusa
-- texto_rico, banner, timeline, metric_card_grid, flip_card, cenario_escolha,
-- match_quiz, roteiro e checklist, todos já existentes em ContentBlocks.js.
--
-- 1. Garmin Connect — o que é o app (reaproveita 41e3caf6, título mantido).
-- 2. Do relógio para o Garmin Connect — timeline de 5 etapas de como o
--    dado chega até o vendedor.
-- 3. O que o cliente encontra no Connect — as 5 grandes áreas de
--    informação (histórico, tendências, treinamento, saúde e bem-estar,
--    integrações), como cards de métrica expansível.
-- 4. Conheça as principais métricas — as 13 métricas do módulo original
--    (mesmos fatos, zero número/especificação nova), agora como Card
--    Giratório (flip), um por métrica: o que é / para que serve / como
--    explicar / na venda, com os avisos de "não é diagnóstico médico" já
--    presentes no conteúdo original preservados e reforçados onde a
--    linguagem antiga sugeria promessa demais (ex.: Status de Treinamento
--    não "evita lesão", só contextualiza a carga).
-- 5. Uma métrica raramente conta toda a história — 4 combinações de
--    métricas analisadas em conjunto, mesmo componente da lição 3.
-- 6. Como explicar uma métrica — 3 cenários definição técnica x explicação
--    de verdade.
-- 7. Associe a necessidade à métrica — quiz de associação, 8 pares
--    necessidade → métrica.
-- 8. Métrica + perfil de cliente — os 4 perfis do estudo de caso original
--    (Ana/Rafael/Cláudia/Bruno) reaproveitados aqui como cenário de decisão
--    (qual métrica mostrar primeiro) + roteiro de apresentação passo a
--    passo para cada um.
-- 9. Como apresentar o Garmin Connect na loja — roteiro de venda em 7
--    passos (pergunte/identifique/escolha/demonstre/explique/conecte/
--    confirme).
-- 10. Música no relógio (reaproveita 16847b04) — mesmo conteúdo, linguagem
--     genericizada por modelo/serviço (evita lista de modelos específicos
--     que fica desatualizada) + cenário de objeção.
-- 11. Garmin Pay (reaproveita 4f9f93a1) — mesmo conteúdo, sem lista de
--     bancos específica (mesma decisão de genericizar), + cenário de
--     objeção.
-- 12. Estudo de caso (reaproveita 8a6d87d8) — os mesmos 4 perfis, agora só
--     como Card Giratório com o roteiro de demonstração completo no verso.
-- 13. Erros comuns na demonstração — checklist interativo, 10 itens.
-- 14. Checklist de integração — checklist interativo, 21 itens
--     (autoavaliação final do colaborador).
-- 15. Encerramento — texto rico + banner de fechamento.
--
-- FLIP CARD COM IMAGEM: o pedido era evoluir o Card Giratório para aceitar
-- uma imagem opcional na frente, sem criar um componente novo. Essa
-- funcionalidade JÁ EXISTE em ContentBlocks.js (campo coverUrl, criado
-- nesta sessão para o Portfólio — ver sql/121/128): quando coverUrl está
-- vazio, o card mostra o texto normalmente (comportamento atual, cards
-- antigos não quebram); quando preenchido, a imagem vira o fundo do card
-- com overlay escuro para manter o texto legível (cover, sem distorcer, sem
-- overflow, funciona no mobile). O editor de conteúdo (textarea de
-- cards_raw) já tem um campo de URL para isso. Por isso nenhuma alteração
-- de código foi necessária: todos os 17 flip cards deste módulo (13
-- métricas + 4 estudo de caso) já têm coverUrl no schema, hoje vazio —
-- pronto para o usuário colar as URLs reais das telas do Garmin Connect
-- depois, sem nenhuma migração nova. Por decisão explícita do brief (não
-- usar ilustração genérica, não inventar screenshot), nenhum emoji ou ícone
-- decorativo foi usado como substituto temporário da imagem.
-- ============================================================================

do $$
declare
  v_module_id uuid := '478e1177-c66a-4f19-adfc-e5e7ed9a605c';
  v_new_lesson_id uuid;
begin
  update lessons set title = 'Garmin Connect', order_index = 0, body = jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Garmin Connect</h3><p><em>Onde os dados do relógio se transformam em informação útil.</em></p><p>O Garmin Connect é o aplicativo que reúne os dados coletados pelo relógio e apresenta essas informações de forma organizada.</p><p>O relógio acompanha atividades, sono, frequência cardíaca e outros dados ao longo do dia e durante os treinos. O Garmin Connect permite visualizar esse histórico, acompanhar tendências e entender melhor a evolução ao longo do tempo.</p><p>É também no aplicativo que o cliente encontra informações complementares, análises, histórico de atividades e integrações com outros serviços.</p><p><strong>Na venda:</strong> \"Uma das grandes vantagens do Garmin é que o relógio não trabalha sozinho. Conforme você usa, o Garmin Connect vai construindo um histórico da sua rotina, dos seus treinos e de diferentes métricas.\"</p>"},{"type":"banner","tone":"info","text":"O relógio continua funcionando normalmente sem o aplicativo. O Garmin Connect amplia a experiência ao organizar histórico, tendências e informações. Não diga que o relógio depende do aplicativo para funcionar."}]'::jsonb) where id = '41e3caf6-0827-4750-a31d-747052b7d658';

  update lessons set title = 'Música no relógio', order_index = 9, body = jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Treinar sem celular</h3><p>Em modelos compatíveis com armazenamento e reprodução de música, o usuário pode manter músicas ou playlists disponíveis no relógio e ouvir por meio de um fone Bluetooth compatível.</p><p>Isso permite sair para correr ou treinar sem precisar levar o celular.</p><p><strong>Na venda:</strong> \"Se você gosta de correr sem celular, podemos verificar um modelo compatível com música para deixar o telefone em casa.\"</p><p><strong>Detalhe importante:</strong> o uso de música exige um fone Bluetooth separado. Isso também pode representar uma oportunidade de venda complementar, quando houver um acessório compatível disponível.</p><h4>Serviços</h4><p><strong>Spotify:</strong> requer assinatura compatível e permite sincronizar playlists para uso no relógio em modelos compatíveis.</p><p><strong>Deezer:</strong> disponível em modelos compatíveis por meio do ecossistema correspondente e exige assinatura ativa.</p><p><strong>Amazon Music:</strong> disponível em modelos selecionados e depende da compatibilidade do serviço e do dispositivo.</p><p><strong>Arquivos pessoais:</strong> alguns modelos permitem armazenamento e reprodução de arquivos de música pessoais.</p>"},{"type":"banner","tone":"warning","text":"A disponibilidade dos serviços e recursos varia conforme modelo, software e serviço. Antes de utilizar esse argumento na venda, confirme a compatibilidade do modelo."},{"type":"cenario_escolha","context":"Cliente: \"Eu gosto de correr sem levar o celular.\"","prompt":"Qual é a melhor resposta?","options":[{"text":"Então você precisa de qualquer Garmin.","correct":false,"feedback":"O argumento é relevante, mas precisa estar ligado ao modelo correto e à necessidade do cliente."},{"text":"Alguns modelos permitem armazenar música no relógio. Posso entender qual modelo faz sentido para seu perfil e verificar essa compatibilidade.","correct":true,"feedback":"O argumento é relevante, mas precisa estar ligado ao modelo correto e à necessidade do cliente."},{"text":"Todo Garmin tem Spotify.","correct":false,"feedback":"O argumento é relevante, mas precisa estar ligado ao modelo correto e à necessidade do cliente."},{"text":"Você precisa comprar um fone Garmin.","correct":false,"feedback":"O argumento é relevante, mas precisa estar ligado ao modelo correto e à necessidade do cliente."}]}]'::jsonb) where id = '16847b04-0fc3-435d-94b5-5e2020cee09b';

  update lessons set title = 'Garmin Pay', order_index = 10, body = jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Praticidade no pulso</h3><p>O Garmin Pay permite realizar pagamentos por aproximação diretamente pelo relógio em modelos compatíveis e com cartões e bancos elegíveis.</p><p>O cliente cadastra o cartão pelo Garmin Connect e utiliza o relógio para realizar o pagamento.</p><p><strong>Na venda:</strong> \"Se você gosta de sair para correr ou treinar sem carteira e sem celular, podemos verificar se o modelo possui Garmin Pay e se o seu cartão é compatível.\"</p>"},{"type":"banner","tone":"warning","text":"Nem todos os modelos possuem NFC. A compatibilidade de cartões e bancos pode variar. Sempre confirme a compatibilidade antes de utilizar Garmin Pay como argumento de venda."},{"type":"cenario_escolha","context":"Cliente: \"Eu não gosto de levar carteira quando vou correr.\"","prompt":"Qual recurso pode ser relevante?","options":[{"text":"Garmin Pay, se o modelo e o cartão forem compatíveis.","correct":true,"feedback":"O recurso faz sentido porque resolve uma necessidade prática apresentada pelo cliente."},{"text":"Sleep Score.","correct":false,"feedback":"O recurso faz sentido porque resolve uma necessidade prática apresentada pelo cliente."},{"text":"Status de Treinamento.","correct":false,"feedback":"O recurso faz sentido porque resolve uma necessidade prática apresentada pelo cliente."},{"text":"Monitoramento de Hábitos.","correct":false,"feedback":"O recurso faz sentido porque resolve uma necessidade prática apresentada pelo cliente."}]}]'::jsonb) where id = '4f9f93a1-439f-401f-a764-d491c21e6cd2';

  update lessons set title = 'Estudo de caso', order_index = 11, body = jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Agora conecte tudo</h3><p>Agora você vai aplicar o conhecimento em quatro situações de cliente.</p><p>A lógica é:</p><p>Perfil → Necessidade → Métricas → Demonstração → Benefício</p>"},{"type":"flip_card","columns":2,"tall":true,"cards":[{"title":"Ana, 34 anos","subtitle":"Home office","coverUrl":"","frontText":"<p><em>\"Quero começar a me movimentar mais.\"</em></p>","backLabel":"Perfil e abordagem","backText":"<p><strong>Perfil:</strong> Trabalha em home office e quer melhorar sua rotina de movimento.</p><p><strong>Métricas relevantes:</strong> Body Battery, Passos, Estresse e Sono.</p><p><strong>Como apresentar:</strong> Comece pelo Body Battery e depois mostre Passos, Estresse e Sleep Score.</p><p>Não transforme a apresentação em uma aula técnica.</p><p>Mostre como as informações podem ajudar Ana a acompanhar sua rotina.</p>"},{"title":"Rafael, 28 anos","subtitle":"Treina 4 vezes por semana","coverUrl":"","frontText":"<p><em>\"Quero começar a correr e evoluir.\"</em></p>","backLabel":"Perfil e abordagem","backText":"<p><strong>Perfil:</strong> Já treina regularmente e quer acompanhar melhor sua evolução.</p><p><strong>Métricas relevantes:</strong> Minutos de Intensidade, Status de Treinamento e Status de VFC.</p><p><strong>Como apresentar:</strong> Comece pela atividade registrada e depois aprofunde nas informações relacionadas ao treinamento e recuperação.</p><p>O objetivo é mostrar contexto, não quantidade de funções.</p>"},{"title":"Cláudia, 42 anos","subtitle":"Executiva","coverUrl":"","frontText":"<p><em>\"Minha rotina é intensa e viajo bastante.\"</em></p>","backLabel":"Perfil e abordagem","backText":"<p><strong>Perfil:</strong> Viaja frequentemente e busca acompanhar melhor sua recuperação.</p><p><strong>Métricas e recursos relevantes:</strong> Sleep Score, Body Battery, Estresse, Garmin Pay e Música.</p><p><strong>Como apresentar:</strong> Comece pela recuperação.</p><p>Depois, se fizer sentido, apresente recursos de praticidade para viagens e treinos.</p>"},{"title":"Bruno, 55 anos","subtitle":"Começando a praticar atividade física","coverUrl":"","frontText":"<p><em>\"Quero algo simples.\"</em></p>","backLabel":"Perfil e abordagem","backText":"<p><strong>Perfil:</strong> Tem pouca familiaridade com tecnologia e precisa de uma experiência simples.</p><p><strong>Informações relevantes:</strong> Batimento Cardíaco, Passos e Sono.</p><p><strong>Como apresentar:</strong> Comece pelo básico.</p><p>Evite apresentar muitas métricas simultaneamente.</p><p>Confirme se Bruno entendeu antes de avançar.</p>"}]}]'::jsonb) where id = '8a6d87d8-7d9b-4afa-9643-7ffebb12cde5';

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Do relógio para o Garmin Connect', 'text', 1, true, jsonb_build_object('blocks', '[{"type":"timeline","items":[{"label":"O relógio coleta","text":"O relógio registra dados durante o uso diário e durante as atividades."},{"label":"Os dados são sincronizados","text":"As informações são enviadas para o Garmin Connect."},{"label":"O app organiza","text":"Os dados passam a ser visualizados em gráficos, históricos e diferentes áreas do aplicativo."},{"label":"O cliente acompanha","text":"O usuário consegue observar informações atuais e acompanhar sua evolução ao longo do tempo."},{"label":"A informação ganha contexto","text":"Uma métrica pode ser analisada junto de outras informações para ajudar o cliente a entender melhor sua rotina e seu treinamento."}]},{"type":"texto_rico","html":"<p>O papel do vendedor não é mostrar todas as telas do Garmin Connect.</p><p>É saber qual informação faz sentido mostrar para aquela pessoa.</p>"}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Do relógio para o Garmin Connect" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'O que o cliente encontra no Connect', 'text', 2, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>O valor está no conjunto de informações</h3><p>O Garmin Connect reúne diferentes informações de saúde, atividade e treinamento.</p><p>A disponibilidade das métricas varia conforme o modelo e os recursos disponíveis no dispositivo.</p><p>Por isso, durante a venda, não basta conhecer a métrica. É importante saber em quais produtos ela está disponível antes de apresentá-la como argumento.</p>"},{"type":"metric_card_grid","columns":2,"items":[{"name":"Histórico","definition":"Permite acompanhar atividades e diferentes informações ao longo do tempo.","tip":"Use o histórico para mostrar ao cliente a própria evolução, não apenas o resultado de um único treino."},{"name":"Tendências","definition":"Ajuda o cliente a observar como determinadas métricas se comportam ao longo do tempo.","tip":"Tendências ajudam a contar uma história, não apenas mostrar um número isolado."},{"name":"Treinamento","definition":"Reúne informações que ajudam o usuário a acompanhar sua rotina de exercícios e evolução.","tip":"É a área mais relevante para clientes que já treinam com regularidade."},{"name":"Saúde e bem-estar","definition":"Apresenta diferentes indicadores relacionados à rotina diária, sono, estresse e outros aspectos monitorados pelo dispositivo.","tip":"É a área mais relevante para clientes que buscam equilíbrio entre rotina, recuperação e bem-estar."},{"name":"Integrações","definition":"O Garmin Connect pode se conectar a serviços e aplicativos compatíveis, ampliando o ecossistema do usuário.","tip":"Confirme a compatibilidade do serviço antes de apresentar uma integração específica."}]},{"type":"texto_rico","html":"<p>O valor não está em ter dezenas de números na tela.</p><p>Está em transformar esses dados em informação que faça sentido para o usuário.</p>"}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "O que o cliente encontra no Connect" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Conheça as principais métricas', 'text', 3, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Reconheça a métrica. Entenda o significado. Saiba explicar.</h3><p>Nesta etapa, você vai conhecer as principais métricas que podem aparecer no Garmin Connect.</p><p>Não tente decorar apenas os nomes.</p><p>Observe:</p><ul><li>O que a métrica representa</li><li>Para que ela serve</li><li>Como explicar</li><li>Quando ela pode ser relevante para um cliente</li></ul>"},{"type":"flip_card","columns":2,"tall":true,"cards":[{"title":"Batimento Cardíaco","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Batimento Cardíaco","backText":"<p><strong>O que é:</strong> Acompanha a frequência cardíaca em diferentes momentos, incluindo repouso e atividades.</p><p><strong>Para que serve:</strong> Ajuda o usuário a acompanhar como a frequência cardíaca se comporta durante a rotina e os treinos.</p><p><strong>Como explicar:</strong> \"Você consegue acompanhar sua frequência cardíaca durante o dia e também observar como ela se comporta durante os exercícios.\"</p><p><strong>Na venda:</strong> É especialmente relevante para clientes que treinam utilizando frequência cardíaca como referência.</p><p><strong>Importante:</strong> Não apresentar a frequência cardíaca do relógio como diagnóstico médico.</p>","coverUrl":""},{"title":"Body Battery","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Body Battery","backText":"<p><strong>O que é:</strong> Indicador de 0 a 100 que ajuda a acompanhar o nível de energia do corpo ao longo do dia.</p><p><strong>Para que serve:</strong> Permite observar como fatores como sono, estresse e atividade influenciam o nível de energia ao longo do dia.</p><p><strong>Como explicar:</strong> \"É uma forma simples de acompanhar como sua energia está se comportando ao longo do dia.\"</p><p><strong>Na venda:</strong> É uma métrica interessante para clientes que querem entender melhor a relação entre rotina, recuperação e energia.</p>","coverUrl":""},{"title":"Estresse","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Estresse","backText":"<p><strong>O que é:</strong> Uma estimativa baseada na variabilidade da frequência cardíaca durante períodos de repouso.</p><p><strong>Para que serve:</strong> Permite visualizar momentos de maior estresse ao longo do dia.</p><p><strong>Como explicar:</strong> \"O relógio consegue mostrar como o seu nível de estresse varia ao longo do dia, inclusive em momentos em que você pode não perceber.\"</p><p><strong>Na venda:</strong> Pode ser relevante para clientes com rotina intensa, trabalho sob pressão ou interesse em acompanhar melhor seu bem-estar.</p><p><strong>Importante:</strong> Não apresentar a métrica como diagnóstico psicológico ou médico.</p>","coverUrl":""},{"title":"Status de VFC","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Status de VFC","backText":"<p><strong>O que é:</strong> Acompanha a variabilidade da frequência cardíaca durante o sono e apresenta uma referência sobre o comportamento dessa métrica ao longo do tempo.</p><p><strong>Para que serve:</strong> Pode ajudar o usuário a acompanhar tendências relacionadas à recuperação e ao equilíbrio fisiológico.</p><p><strong>Como explicar:</strong> \"Em vez de olhar apenas para a frequência cardíaca, você consegue acompanhar como a variação entre os batimentos está se comportando ao longo do tempo.\"</p><p><strong>Na venda:</strong> É especialmente relevante para clientes que treinam com frequência e demonstram interesse em recuperação e acompanhamento mais avançado.</p>","coverUrl":""},{"title":"Sleep Score","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Sleep Score","backText":"<p><strong>O que é:</strong> Uma pontuação que resume diferentes informações relacionadas ao sono.</p><p><strong>Para que serve:</strong> Ajuda o usuário a acompanhar a qualidade e o comportamento do sono.</p><p><strong>Como explicar:</strong> \"Em vez de olhar apenas quantas horas você dormiu, o aplicativo reúne diferentes informações do sono em uma visão mais simples.\"</p><p><strong>Na venda:</strong> É relevante para clientes interessados em recuperação, rotina, bem-estar ou performance.</p>","coverUrl":""},{"title":"Status de Treinamento","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Status de Treinamento","backText":"<p><strong>O que é:</strong> Uma análise que considera informações relacionadas à carga de treinamento e evolução do condicionamento.</p><p><strong>Para que serve:</strong> Ajuda o usuário a entender como a rotina recente de treinamento está se relacionando com sua evolução.</p><p><strong>Como explicar:</strong> \"Ele ajuda a colocar seus treinos em contexto, mostrando como sua carga recente está relacionada à sua evolução.\"</p><p><strong>Na venda:</strong> É especialmente relevante para clientes que treinam regularmente e querem acompanhar evolução, carga e adaptação ao treinamento.</p><p><strong>Importante:</strong> Não dizer que o Status de Treinamento prevê ou evita lesões.</p>","coverUrl":""},{"title":"Passos","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Passos","backText":"<p><strong>O que é:</strong> Contagem diária de passos com acompanhamento de metas.</p><p><strong>Para que serve:</strong> Ajuda o usuário a acompanhar seu nível de movimento e consistência ao longo do tempo.</p><p><strong>Como explicar:</strong> \"Você consegue acompanhar quanto se movimenta durante o dia e observar sua consistência ao longo da semana e do mês.\"</p><p><strong>Na venda:</strong> É uma métrica simples e relevante para quem quer começar a se movimentar mais ou acompanhar sua rotina diária.</p>","coverUrl":""},{"title":"Calorias","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Calorias","backText":"<p><strong>O que é:</strong> Estimativa do gasto calórico diário, incluindo componentes relacionados ao metabolismo e à atividade.</p><p><strong>Para que serve:</strong> Ajuda o usuário a acompanhar o gasto energético estimado ao longo do dia.</p><p><strong>Como explicar:</strong> \"O relógio estima seu gasto de energia e permite acompanhar esse dado junto da sua rotina e atividades.\"</p><p><strong>Na venda:</strong> Pode ser relevante para clientes interessados em atividade física, composição corporal ou acompanhamento da rotina.</p>","coverUrl":""},{"title":"Minutos de Intensidade","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Minutos de Intensidade","backText":"<p><strong>O que é:</strong> Registro do tempo dedicado a atividades de intensidade moderada ou vigorosa.</p><p><strong>Para que serve:</strong> Ajuda o usuário a acompanhar o volume de atividade física ao longo da semana.</p><p><strong>Como explicar:</strong> \"Em vez de contar apenas os treinos, você consegue acompanhar quanto tempo passou realmente em atividades de maior intensidade.\"</p><p><strong>Na venda:</strong> É interessante para clientes que querem acompanhar consistência e volume de atividade física.</p>","coverUrl":""},{"title":"SpO2","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"SpO2","backText":"<p><strong>O que é:</strong> Medição da saturação de oxigênio no sangue em dispositivos que possuem o sensor e recurso correspondente.</p><p><strong>Para que serve:</strong> Pode ajudar o usuário a acompanhar tendências de saturação de oxigênio em determinados períodos.</p><p><strong>Como explicar:</strong> \"É uma informação adicional que pode ser acompanhada pelo relógio em modelos compatíveis.\"</p><p><strong>Na venda:</strong> Pode ser relevante para determinados perfis interessados em monitoramento mais completo.</p><p><strong>Importante:</strong> Não apresentar SpO2 como ferramenta de diagnóstico. Não afirmar que o relógio identifica ou diagnostica apneia, doenças respiratórias ou outras condições médicas.</p>","coverUrl":""},{"title":"Ciclo Menstrual","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Ciclo Menstrual","backText":"<p><strong>O que é:</strong> Recurso para registrar e acompanhar informações relacionadas ao ciclo menstrual.</p><p><strong>Para que serve:</strong> Ajuda a usuária a acompanhar seu ciclo dentro do ecossistema Garmin.</p><p><strong>Como explicar:</strong> \"Você consegue registrar informações do seu ciclo e acompanhar esse histórico junto de outros dados da sua rotina.\"</p><p><strong>Na venda:</strong> Pode ser relevante para clientes que procuram um relógio com recursos de acompanhamento de saúde feminina.</p><p><strong>Importante:</strong> Não apresentar o recurso como diagnóstico médico.</p>","coverUrl":""},{"title":"Hidratação","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Hidratação","backText":"<p><strong>O que é:</strong> Registro do consumo de água dentro do ecossistema Garmin, conforme os recursos disponíveis.</p><p><strong>Para que serve:</strong> Ajuda o usuário a acompanhar sua rotina de hidratação.</p><p><strong>Como explicar:</strong> \"Você pode registrar sua ingestão de água e acompanhar esse hábito ao longo do tempo.\"</p><p><strong>Na venda:</strong> Pode ser relevante para clientes interessados em criar uma rotina mais consistente de autocuidado.</p>","coverUrl":""},{"title":"Monitoramento de Hábitos","subtitle":"Reconheça esta métrica","frontText":"","backLabel":"Monitoramento de Hábitos","backText":"<p><strong>O que é:</strong> Ferramenta para acompanhar hábitos e metas pessoais.</p><p><strong>Para que serve:</strong> Ajuda o usuário a visualizar sua consistência ao longo do tempo.</p><p><strong>Como explicar:</strong> \"Em vez de olhar apenas para um dia, você consegue acompanhar a consistência dos seus hábitos ao longo do mês.\"</p><p><strong>Na venda:</strong> É interessante para clientes que buscam acompanhamento de rotina e consistência.</p>","coverUrl":""}]}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Conheça as principais métricas" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Uma métrica raramente conta toda a história', 'text', 4, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Olhe para o conjunto</h3><p>Uma das maiores diferenças entre conhecer uma métrica e entender o Garmin Connect é perceber que os dados podem ser analisados em conjunto.</p>"},{"type":"metric_card_grid","columns":2,"items":[{"name":"Sono + Body Battery","definition":"O sono ajuda a contextualizar como o usuário começou o dia e o Body Battery mostra como a energia está se comportando ao longo do tempo.","tip":"Use essa combinação para clientes que perguntam por que se sentem cansados mesmo depois de dormir."},{"name":"Estresse + Body Battery","definition":"O cliente pode observar momentos de maior estresse e como isso aparece junto de outras informações relacionadas à energia.","tip":"Use essa combinação para clientes com rotina de trabalho intensa."},{"name":"Treinamento + VFC","definition":"Para quem treina regularmente, acompanhar treinamento e tendências de VFC pode ajudar a contextualizar a recuperação.","tip":"Use essa combinação para clientes que treinam com frequência e querem entender melhor a recuperação."},{"name":"Passos + Monitoramento de Hábitos","definition":"A quantidade de passos mostra um dado diário. O histórico de hábitos ajuda a visualizar consistência.","tip":"Use essa combinação para clientes que querem acompanhar consistência, não apenas um número isolado."}]},{"type":"texto_rico","html":"<p>O objetivo não é mostrar quatro métricas ao mesmo tempo.</p><p>É escolher as informações que ajudam aquele cliente a entender melhor o próprio objetivo.</p>"}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Uma métrica raramente conta toda a história" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Como explicar uma métrica', 'text', 5, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Você sabe explicar ou só sabe definir?</h3>"},{"type":"cenario_escolha","context":"Cliente: \"Esse Body Battery serve para quê?\"","prompt":"Qual a melhor resposta?","options":[{"text":"É uma métrica de 0 a 100.","correct":false,"feedback":"Uma definição técnica não é necessariamente uma boa explicação. O cliente precisa entender o significado daquela informação no contexto da própria rotina."},{"text":"Ele ajuda você a acompanhar como sua energia está se comportando ao longo do dia.","correct":true,"feedback":"Uma definição técnica não é necessariamente uma boa explicação. O cliente precisa entender o significado daquela informação no contexto da própria rotina."},{"text":"É uma função que mostra se você está saudável.","correct":false,"feedback":"Uma definição técnica não é necessariamente uma boa explicação. O cliente precisa entender o significado daquela informação no contexto da própria rotina."},{"text":"É a bateria do relógio.","correct":false,"feedback":"Uma definição técnica não é necessariamente uma boa explicação. O cliente precisa entender o significado daquela informação no contexto da própria rotina."}]},{"type":"cenario_escolha","context":"Cliente: \"Para que serve o Sleep Score?\"","prompt":"Qual a melhor resposta?","options":[{"text":"É uma pontuação do sono.","correct":false,"feedback":"Uma boa explicação traduz a função para algo que o cliente consegue visualizar."},{"text":"Ele resume diferentes informações do seu sono para ajudar você a entender como foi sua noite.","correct":true,"feedback":"Uma boa explicação traduz a função para algo que o cliente consegue visualizar."},{"text":"Ele diz se você está saudável.","correct":false,"feedback":"Uma boa explicação traduz a função para algo que o cliente consegue visualizar."},{"text":"Ele mede apenas quantas horas você dormiu.","correct":false,"feedback":"Uma boa explicação traduz a função para algo que o cliente consegue visualizar."}]},{"type":"cenario_escolha","context":"Cliente: \"Por que eu deveria olhar meu Status de Treinamento?\"","prompt":"Qual a melhor resposta?","options":[{"text":"Porque é uma das funções mais avançadas.","correct":false,"feedback":"O argumento deve estar ligado ao benefício real da informação, sem prometer resultados que a métrica não entrega."},{"text":"Porque todo atleta precisa usar.","correct":false,"feedback":"O argumento deve estar ligado ao benefício real da informação, sem prometer resultados que a métrica não entrega."},{"text":"Porque ele coloca seus treinos recentes em contexto e ajuda você a acompanhar sua evolução.","correct":true,"feedback":"O argumento deve estar ligado ao benefício real da informação, sem prometer resultados que a métrica não entrega."},{"text":"Porque ele evita lesões.","correct":false,"feedback":"O argumento deve estar ligado ao benefício real da informação, sem prometer resultados que a métrica não entrega."}]}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Como explicar uma métrica" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Associe a necessidade à métrica', 'text', 6, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Qual informação faz mais sentido?</h3>"},{"type":"match_quiz","pairs":[{"term":"Quero acompanhar como minha energia varia durante o dia.","definition":"Body Battery"},{"term":"Quero entender melhor como estou dormindo.","definition":"Sleep Score"},{"term":"Quero acompanhar meu nível de estresse ao longo do dia.","definition":"Estresse"},{"term":"Quero acompanhar tendências relacionadas à recuperação.","definition":"Status de VFC"},{"term":"Quero acompanhar minha evolução nos treinos.","definition":"Status de Treinamento"},{"term":"Quero acompanhar quanto me movimento durante o dia.","definition":"Passos"},{"term":"Quero acompanhar meu volume de atividade física.","definition":"Minutos de Intensidade"},{"term":"Quero acompanhar meu gasto energético estimado.","definition":"Calorias"}]},{"type":"texto_rico","html":"<p>Não existe uma métrica que seja \"a melhor\".</p><p>Existe a métrica mais relevante para aquilo que o cliente quer acompanhar.</p>"}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Associe a necessidade à métrica" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Métrica + perfil de cliente', 'text', 7, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Qual informação você mostraria primeiro?</h3><p>Na loja, você não precisa apresentar todas as métricas disponíveis.</p><p>Comece pelo que tem relação com o objetivo do cliente.</p>"},{"type":"texto_rico","html":"<h4>Ana, 34 anos</h4><p>Trabalha em home office e passa boa parte do dia sentada.</p><p>Tem dois filhos, nunca praticou esporte com regularidade e quer começar a se movimentar mais sem transformar isso em uma rotina pesada.</p><p><strong>Necessidades:</strong> movimento, rotina, sono, estresse e energia.</p>"},{"type":"cenario_escolha","context":"","prompt":"Qual conjunto de informações faz mais sentido apresentar primeiro?","options":[{"text":"VO2 Max, Status de Treinamento e potência.","correct":false,"feedback":"Ana ainda não está procurando performance esportiva. A apresentação deve começar por informações que tenham relação direta com a rotina que ela quer melhorar."},{"text":"Body Battery, Passos, Estresse e Sono.","correct":true,"feedback":"Ana ainda não está procurando performance esportiva. A apresentação deve começar por informações que tenham relação direta com a rotina que ela quer melhorar."},{"text":"Mapas, navegação e altitude.","correct":false,"feedback":"Ana ainda não está procurando performance esportiva. A apresentação deve começar por informações que tenham relação direta com a rotina que ela quer melhorar."},{"text":"Métricas avançadas de corrida.","correct":false,"feedback":"Ana ainda não está procurando performance esportiva. A apresentação deve começar por informações que tenham relação direta com a rotina que ela quer melhorar."}]},{"type":"roteiro","steps":[{"title":"Mostre o Body Battery."},{"title":"Explique de forma simples o que a informação representa."},{"title":"Mostre os Passos."},{"title":"Mostre o Estresse."},{"title":"Mostre o Sleep Score."},{"title":"Relacione as informações sem sobrecarregar a cliente."}]},{"type":"banner","tone":"warning","text":"Não definir uma meta específica de passos como regra universal. A meta deve ser individualizada."},{"type":"texto_rico","html":"<h4>Rafael, 28 anos</h4><p>Treina na academia quatro vezes por semana e quer começar a correr.</p><p>Já entende de treinamento, mas ainda não utiliza dados avançados para acompanhar sua evolução.</p><p><strong>Necessidades:</strong> treinamento, evolução, recuperação e consistência.</p>"},{"type":"cenario_escolha","context":"","prompt":"Quais informações fazem mais sentido?","options":[{"text":"Passos e hidratação apenas.","correct":false,"feedback":"Rafael já demonstra interesse em treinamento e evolução. Faz mais sentido aprofundar a conversa com informações relacionadas à carga, treinamento e recuperação."},{"text":"Minutos de Intensidade, Status de Treinamento e Status de VFC.","correct":true,"feedback":"Rafael já demonstra interesse em treinamento e evolução. Faz mais sentido aprofundar a conversa com informações relacionadas à carga, treinamento e recuperação."},{"text":"Garmin Pay e música.","correct":false,"feedback":"Rafael já demonstra interesse em treinamento e evolução. Faz mais sentido aprofundar a conversa com informações relacionadas à carga, treinamento e recuperação."},{"text":"Ciclo menstrual.","correct":false,"feedback":"Rafael já demonstra interesse em treinamento e evolução. Faz mais sentido aprofundar a conversa com informações relacionadas à carga, treinamento e recuperação."}]},{"type":"roteiro","steps":[{"title":"Abra uma atividade registrada."},{"title":"Mostre os dados de frequência cardíaca."},{"title":"Mostre Minutos de Intensidade."},{"title":"Mostre o Status de Treinamento."},{"title":"Mostre o Status de VFC."},{"title":"Explique como essas informações podem ser acompanhadas ao longo do tempo."}]},{"type":"texto_rico","html":"<h4>Cláudia, 42 anos</h4><p>Executiva, viaja com frequência e tem uma rotina intensa.</p><p>Quer acompanhar melhor sua recuperação e valoriza praticidade durante viagens e treinos.</p><p><strong>Necessidades:</strong> recuperação, sono, rotina intensa e praticidade.</p>"},{"type":"cenario_escolha","context":"","prompt":"Qual abordagem faz mais sentido?","options":[{"text":"Mostrar apenas métricas de corrida.","correct":false,"feedback":"A necessidade principal da cliente deve definir o início da demonstração. Depois que a necessidade principal estiver atendida, recursos de praticidade podem complementar a apresentação."},{"text":"Mostrar Body Battery, Sleep Score e Estresse e depois apresentar recursos de praticidade como Garmin Pay e Música, quando disponíveis e compatíveis.","correct":true,"feedback":"A necessidade principal da cliente deve definir o início da demonstração. Depois que a necessidade principal estiver atendida, recursos de praticidade podem complementar a apresentação."},{"text":"Mostrar apenas design.","correct":false,"feedback":"A necessidade principal da cliente deve definir o início da demonstração. Depois que a necessidade principal estiver atendida, recursos de praticidade podem complementar a apresentação."},{"text":"Mostrar apenas passos.","correct":false,"feedback":"A necessidade principal da cliente deve definir o início da demonstração. Depois que a necessidade principal estiver atendida, recursos de praticidade podem complementar a apresentação."}]},{"type":"roteiro","steps":[{"title":"Mostre Sleep Score."},{"title":"Mostre Body Battery."},{"title":"Mostre Estresse."},{"title":"Pergunte se praticidade durante viagens também é importante."},{"title":"Se fizer sentido e o modelo possuir os recursos, apresente Garmin Pay e Música."}]},{"type":"texto_rico","html":"<h4>Bruno, 55 anos</h4><p>Está começando a praticar atividade física e tem pouca familiaridade com tecnologia.</p><p>Quer acompanhar informações básicas da rotina e prefere uma experiência simples.</p><p><strong>Necessidades:</strong> simplicidade, movimento e acompanhamento da rotina.</p>"},{"type":"cenario_escolha","context":"","prompt":"Qual é a melhor abordagem?","options":[{"text":"Mostrar todas as métricas avançadas.","correct":false,"feedback":"Conhecer o produto também significa saber o que <strong>não</strong> mostrar naquele momento. Um cliente iniciante precisa primeiro entender o básico."},{"text":"Começar por informações simples e fáceis de entender, como passos, sono e frequência cardíaca, e aprofundar somente se houver interesse.","correct":true,"feedback":"Conhecer o produto também significa saber o que <strong>não</strong> mostrar naquele momento. Um cliente iniciante precisa primeiro entender o básico."},{"text":"Começar pelo Status de Treinamento.","correct":false,"feedback":"Conhecer o produto também significa saber o que <strong>não</strong> mostrar naquele momento. Um cliente iniciante precisa primeiro entender o básico."},{"text":"Começar por configurações avançadas.","correct":false,"feedback":"Conhecer o produto também significa saber o que <strong>não</strong> mostrar naquele momento. Um cliente iniciante precisa primeiro entender o básico."}]}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Métrica + perfil de cliente" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Como apresentar o Garmin Connect na loja', 'text', 8, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Uma boa demonstração começa antes de abrir o aplicativo</h3><p>Não abra o Garmin Connect e comece a mostrar tudo.</p><p>Primeiro descubra o que o cliente quer acompanhar.</p>"},{"type":"roteiro","steps":[{"title":"Pergunte","dialog":"O que você gostaria de acompanhar no seu dia a dia ou nos seus treinos?"},{"title":"Identifique","tip":"Entenda se a prioridade é treinamento, recuperação, sono, saúde e bem-estar, rotina ou praticidade."},{"title":"Escolha","tip":"Selecione uma ou duas informações mais relevantes."},{"title":"Demonstre","tip":"Mostre a informação diretamente no Garmin Connect."},{"title":"Explique","tip":"Traduza a métrica para uma linguagem simples."},{"title":"Conecte","tip":"Mostre outra informação apenas se ela ajudar a complementar a primeira."},{"title":"Confirme","dialog":"Isso é próximo do que você gostaria de acompanhar?"}]},{"type":"texto_rico","html":"<p>Uma boa demonstração não mostra tudo.</p><p>Mostra o que importa.</p>"}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Como apresentar o Garmin Connect na loja" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Erros comuns na demonstração', 'text', 12, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>O que evitar</h3><p>Conhecer muitas funções não significa saber apresentar bem o produto.</p><p>Marque os comportamentos que você deve evitar.</p>"},{"type":"checklist","items":["Mostrar todas as métricas disponíveis de uma vez.","Começar a demonstração sem entender o objetivo do cliente.","Usar termos técnicos sem explicar.","Apresentar uma métrica como diagnóstico médico.","Falar de recursos que não estão disponíveis naquele modelo.","Prometer uma função sem confirmar compatibilidade.","Mostrar uma informação que não tem relação com a necessidade apresentada.","Transformar a demonstração em uma lista de especificações.","Falar mais do que ouvir.","Apresentar recursos avançados para um cliente que ainda não entendeu o básico."],"reflection":"Uma boa demonstração não mostra tudo. Mostra o que importa para aquela pessoa."}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Erros comuns na demonstração" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Checklist de integração', 'text', 13, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Estou pronto para apresentar o Garmin Connect?</h3>"},{"type":"checklist","items":["Sei explicar o que é o Garmin Connect.","Sei explicar o papel do relógio e do aplicativo.","Reconheço as principais métricas.","Sei explicar Body Battery.","Sei explicar Estresse.","Sei explicar Status de VFC.","Sei explicar Sleep Score.","Sei explicar Status de Treinamento.","Sei explicar Passos.","Sei explicar Minutos de Intensidade.","Sei explicar Calorias.","Sei explicar SpO2 sem apresentar como diagnóstico.","Sei explicar os recursos de acompanhamento do ciclo menstrual.","Sei explicar Hidratação.","Sei explicar Monitoramento de Hábitos.","Sei relacionar uma métrica com uma necessidade.","Sei escolher o que mostrar primeiro.","Sei adaptar a demonstração ao nível de conhecimento do cliente.","Sei verificar se uma função está disponível no modelo apresentado.","Sei apresentar Música quando fizer sentido.","Sei apresentar Garmin Pay quando fizer sentido.","Consigo demonstrar o Garmin Connect sem sobrecarregar o cliente."]}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Checklist de integração" do módulo Garmin Connect.';
  end if;

  insert into lessons (module_id, title, content_type, order_index, is_published, body)
  values (v_module_id, 'Encerramento', 'text', 14, true, jsonb_build_object('blocks', '[{"type":"texto_rico","html":"<h3>Dados só têm valor quando fazem sentido</h3><p>O Garmin Connect reúne uma grande quantidade de informações.</p><p>Mas o papel do vendedor não é mostrar todas elas.</p><p>É entender qual informação importa para aquela pessoa e transformar um número em algo que ela consiga compreender.</p><p>Um cliente interessado em performance precisa de uma demonstração diferente de alguém que quer acompanhar a rotina, dormir melhor ou simplesmente começar a se movimentar.</p><p>Por isso, o conhecimento de produto precisa estar conectado ao conhecimento do cliente.</p><p>A lógica é simples:</p><p class=\"cb-model-heading\"><strong>ENTENDER A PESSOA → IDENTIFICAR A NECESSIDADE → ESCOLHER A INFORMAÇÃO → DEMONSTRAR → EXPLICAR → CONECTAR AO BENEFÍCIO</strong></p>"},{"type":"banner","tone":"success","text":"Conhecer as métricas é importante. Saber quando apresentá-las é o que transforma conhecimento de produto em atendimento consultivo."}]'::jsonb))
  returning id into v_new_lesson_id;

  if v_new_lesson_id is null then
    raise exception 'Falha ao inserir a lição "Encerramento" do módulo Garmin Connect.';
  end if;

end $$;

